write_table(data.frame(medida=names(desc(d$Magnitude)),Magnitude=desc(d$Magnitude),Depth=desc(d$Depth)),'descritiva')
write_table(as.data.frame(table(raw$Type,useNA='ifany')),'tipos_evento')
write_table(as.data.frame(table(d$`Magnitude Type`,useNA='ifany')),'tipos_magnitude')
write_table(as.data.frame(table(d$ano,d$`Magnitude Type`,useNA='ifany')),'tipos_por_ano')
write_table(as.data.frame(table(d$ano)),'eventos_ano')
write_table(head(d[order(-d$Magnitude,d$timestamp),c('data','Magnitude','Depth','Latitude','Longitude','Magnitude Type','ID','regiao')],20),'maiores')
fig('exploratoria',function(){par(mfrow=c(2,2));hist(d$Magnitude,breaks=35,prob=TRUE,col='#b8ded8',main='Distribuição da magnitude',xlab='Magnitude');lines(density(d$Magnitude),col='#007f78',lwd=2);boxplot(d$Magnitude,horizontal=TRUE,main='Dispersão da magnitude',xlab='Magnitude',col='#b8ded8');hist(d$Depth,breaks=45,col='#b8ded8',main='Profundidade',xlab='Profundidade (km)');plot(d$Depth,d$Magnitude,pch=16,cex=.25,col=adjustcolor('#007f78',.15),main='Magnitude e profundidade',xlab='Profundidade (km)',ylab='Magnitude')})
fig('temporal',function(){par(mfrow=c(2,1));plot(table(d$ano),type='h',main='Terremotos catalogados por ano',xlab='Ano',ylab='Eventos');plot(d$data,d$Magnitude,pch=16,cex=.3,col=adjustcolor('#007f78',.2),main='Magnitude ao longo do tempo',xlab='Data',ylab='Magnitude')})
fig('escalas',function(){mat<-table(d$`Magnitude Type`,d$ano);barplot(prop.table(mat,2),space=0,col=hcl.colors(nrow(mat),'Spectral'),border=NA,xlab='Ano',ylab='Proporção',main='Composição das escalas de magnitude');legend('topright',rownames(mat),fill=hcl.colors(nrow(mat),'Spectral'),cex=.65,ncol=3)})
